INSERT INTO daily_task.tbl_scwts_sarujanan (activity_id, activity_date, developer, project_code, project_name, requirement_id, deliverable_id, activity_type, activity_title, activity_summary, systems_touched, files_touched, evidence_refs, reusable_asset_created, reusable_pattern, validation_rule, gap_or_risk, next_action, status, priority, llm_queryable, company_knowledge_candidate, memory_tags, source_skill_file, source_type)
VALUES ('D01-A02', DATE '2026-07-31', 'sarujanan', 'scwts', 'Supplier-to-Customer Workflow Tracking System', 'REQ-02', 'D01', 'investigation', 'Discover the source database being dismantled mid-session', 'While validating, public.inv_products, public.inv_product_combo, public.amazon_returns and all six supplier.* tables dropped to 0 rows, and public.ebay_returns and public.shopify_returns were dropped outright. listing_data, order_transaction, traffic_data and ppc_performance survived. Dashboard V2''s hard gates caught this and correctly refused to publish, so neither the live dashboard nor the hub copy was overwritten.', 'PostgreSQL order_management_copy', 'logs/automation_v2.log', '4 tables emptied to 0 rows; 2 tables dropped; V2 build exited 1 without publishing', FALSE, 'Hard validation gates that block publish are what turn a data outage into a safe no-op', 'Source-availability probe runs before any dependent query and records row counts', 'Dashboard V2''s scheduled 11:00 run will keep failing until it is repointed at the ledsone database', 'Repoint Dashboard V2 at ledsone or accept a red cron', 'completed', 'high', TRUE, TRUE, 'data-migration,source-outage,validation-gate,incident', '2026-07-31__sarujanan__scwts__REQ-02-D01.md', 'skill_file')
