INSERT INTO daily_task.tbl_scwts_sarujanan (activity_id, activity_date, developer, project_code, project_name, requirement_id, deliverable_id, activity_type, activity_title, activity_summary, systems_touched, files_touched, evidence_refs, reusable_asset_created, reusable_pattern, validation_rule, gap_or_risk, next_action, status, priority, llm_queryable, company_knowledge_candidate, memory_tags, source_skill_file, source_type)
VALUES ('D01-A04', DATE '2026-07-31', 'sarujanan', 'scwts', 'Supplier-to-Customer Workflow Tracking System', 'REQ-02', 'D01', 'implementation', 'Build Dashboard V3 as an independent container-first deliverable', 'Created Dashboard V3 in new dashboard-v3 and dashboard-v3-sql folders, leaving Dashboard V2 completely untouched (MD5 unchanged). Scope is driven by the Google Sheet rather than the database, which is the core difference from V2. Row grain is one row per container, product and marketplace, with the product being the combo where one exists and the component otherwise.', 'PostgreSQL order_management_copy; local filesystem', 'dashboard-v3-sql/build_v3.py; dashboard-v3-sql/payload_v3.json; dashboard-v3/index.html', '781 rows across 6 containers; 209 components; 295 combos', TRUE, 'Sheet-driven scope: a business-owned spreadsheet defines what is in scope, the database supplies the detail', 'No duplicate container-product-marketplace rows; fan-out gate carried over from V2', 'Component to Combo mapping is inferred from SKU naming because inv_product_combo is empty', 'Get inv_product_combo migrated so the mapping stops being an inference', 'completed', 'high', TRUE, TRUE, 'dashboard-v3,container-view,sheet-driven-scope', '2026-07-31__sarujanan__scwts__REQ-02-D01.md', 'skill_file')
