INSERT INTO daily_task.tbl_scwts_sarujanan (activity_id, activity_date, developer, project_code, project_name, requirement_id, deliverable_id, activity_type, activity_title, activity_summary, systems_touched, files_touched, evidence_refs, reusable_asset_created, reusable_pattern, validation_rule, gap_or_risk, next_action, status, priority, llm_queryable, company_knowledge_candidate, memory_tags, source_skill_file, source_type)
VALUES ('D01-A05', DATE '2026-07-31', 'sarujanan', 'scwts', 'Supplier-to-Customer Workflow Tracking System', 'REQ-02', 'D01', 'bugfix', 'Swap the inv_products source to LEDs One inventory.products', 'public.inv_products is a stale dead copy (0 rows) on the project database, so per instruction the only source swapped was inv_products, which now comes from the LEDs One MCP inventory.products. No direct credentials exist for ledsone so the master was extracted in three exact-SKU chunks into a local cache. A regex scan across all 43,949 products timed out over MCP whereas exact-SKU ANY(ARRAY[...]) lookups return instantly.', 'PostgreSQL ledsone (LEDs One MCP); PostgreSQL order_management_copy', 'dashboard-v3-sql/ledsone_products.json; dashboard-v3-sql/build_v3.py', '420 products cached; Component Created Dates 775/776 populated', TRUE, 'Chunked exact-SKU extraction over MCP; avoid regex scans that time out', 'Component and Combo Created Dates must come from LEDs One, never from the stale copy', '84 combo SKUs (mostly locale variants) and 1 component (PCRMFF) are absent from inventory.products', 'Ask whether the missing locale-variant SKUs should exist as products', 'completed', 'high', TRUE, TRUE, 'ledsone,inv-products,source-of-truth,mcp-extraction', '2026-07-31__sarujanan__scwts__REQ-02-D01.md', 'skill_file')
