VALUES ('D01-A06', DATE '2026-07-31', 'sarujanan', 'scwts', 'Supplier-to-Customer Workflow Tracking System', 'REQ-02', 'D01', 'enhancement', 'Apply the requested V3 UI changes only', 'Removed the Supplier and Received Date columns leaving 18, and added a Container tab list with live per-container counts plus an All Containers tab. The grouped product layout, filters, search, sorting, pagination, CSV export, theme and responsive behaviour were kept identical to Dashboard V2.', 'local filesystem', 'dashboard-v3-sql/make_html_v3.py; dashboard-v3/index.html', '18 columns; 6 container tabs; rows per container 83/325/165/91/2/110', FALSE, 'Reuse the prior version''s style block verbatim so a new dashboard inherits the whole design system', 'Supplier and Received Date must not appear in the V3 column set', 'None', 'Monitor whether users want container filtering combined with marketplace filtering', 'completed', 'medium', TRUE, TRUE, 'dashboard-v3,ui,container-tabs', '2026-07-31__sarujanan__scwts__REQ-02-D01.md', 'skill_file')
