INSERT INTO daily_task.tbl_scwts_sarujanan (activity_id, activity_date, developer, project_code, project_name, requirement_id, deliverable_id, activity_type, activity_title, activity_summary, systems_touched, files_touched, evidence_refs, reusable_asset_created, reusable_pattern, validation_rule, gap_or_risk, next_action, status, priority, llm_queryable, company_knowledge_candidate, memory_tags, source_skill_file, source_type)
VALUES ('D01-A07', DATE '2026-07-31', 'sarujanan', 'scwts', 'Supplier-to-Customer Workflow Tracking System', 'REQ-02', 'D01', 'enhancement', 'Add Dashboard V2''s detail drawer to V3', 'Ported V2''s click-through side drawer with identical markup, CSS, open and close behaviour, Escape handling, backdrop click and the reflow fix that prevents an invisible overlay swallowing clicks. V2''s Supply chain card was replaced by a Container card because Supplier and Received Date no longer exist in V3. The multi-component stack behaviour is preserved: values collapse when all components agree and list separately when they differ.', 'local filesystem', 'dashboard-v3-sql/make_html_v3.py; dashboard-v3/index.html', 'All 781 rows are drawer-addressable via a RENDERED index rebuilt each render', FALSE, 'Rebuild the row-to-record index on every render so drawers stay correct across tabs, filters and paging', 'Drawer index must be rebuilt on every render, not cached', 'None', 'None', 'completed', 'medium', TRUE, TRUE, 'dashboard-v3,drawer,ui-parity', '2026-07-31__sarujanan__scwts__REQ-02-D01.md', 'skill_file')
