INSERT INTO daily_task.tbl_scwts_sarujanan (activity_id, activity_date, developer, project_code, project_name, requirement_id, deliverable_id, activity_type, activity_title, activity_summary, systems_touched, files_touched, evidence_refs, reusable_asset_created, reusable_pattern, validation_rule, gap_or_risk, next_action, status, priority, llm_queryable, company_knowledge_candidate, memory_tags, source_skill_file, source_type)
VALUES ('D01-A08', DATE '2026-08-03', 'sarujanan', 'scwts', 'Supplier-to-Customer Workflow Tracking System', 'REQ-02', 'D01', 'bugfix', 'Fix Component Images being taken from the marketplace instead of the Google Sheet', 'Varmen reported LHPVHRE27WH showing the wrong image. Root cause was a one-word bug: the image map was populated from listing_data first and the sheet image was then applied with dict.setdefault, which is a no-op when the key already exists. Every SKU that had a marketplace listing therefore kept the marketplace photo and the sheet image was silently discarded, the exact opposite of the code comment. Fixed by assigning directly so the sheet always wins, leaving listing_data as fallback only.', 'Google Sheet; PostgreSQL order_management_copy', 'dashboard-v3-sql/build_v3.py; dashboard-v3/index.html', '95 SKUs corrected; 207/209 components now render the sheet image; LHPVHRE27WH now Productimages/23713.jpeg', FALSE, 'setdefault silently loses a precedence override - assign directly when the later source must win', 'Component Image must equal the Google Sheet Image Link for every SKU that has one', '2 components (PCRMFF, SPPGUK3PGD) have a blank Image Link in the sheet', 'Ask Varmen to fill the 2 missing Image Link cells', 'completed', 'high', TRUE, TRUE, 'bugfix,image-mapping,google-sheet,setdefault-trap', '2026-07-31__sarujanan__scwts__REQ-02-D01.md', 'skill_file')
ON CONFLICT (project_code, activity_id) DO UPDATE SET activity_date=EXCLUDED.activity_date, developer=EXCLUDED.developer, project_name=EXCLUDED.project_name, requirement_id=EXCLUDED.requirement_id, deliverable_id=EXCLUDED.deliverable_id, activity_type=EXCLUDED.activity_type, activity_title=EXCLUDED.activity_title, activity_summary=EXCLUDED.activity_summary, systems_touched=EXCLUDED.systems_touched, files_touched=EXCLUDED.files_touched, evidence_refs=EXCLUDED.evidence_refs, reusable_asset_created=EXCLUDED.reusable_asset_created, reusable_pattern=EXCLUDED.reusable_pattern, validation_rule=EXCLUDED.validation_rule, gap_or_risk=EXCLUDED.gap_or_risk, next_action=EXCLUDED.next_action, status=EXCLUDED.status, priority=EXCLUDED.priority, llm_queryable=EXCLUDED.llm_queryable, company_knowledge_candidate=EXCLUDED.company_knowledge_candidate, memory_tags=EXCLUDED.memory_tags, source_skill_file=EXCLUDED.source_skill_file, source_type=EXCLUDED.source_type, updated_at=now();

INSERT INTO daily_task.tbl_scwts_sarujanan (activity_id, activity_date, developer, project_code, project_name, requirement_id, deliverable_id, activity_type, activity_title, activity_summary, systems_touched, files_touched, evidence_refs, reusable_asset_created, reusable_pattern, validation_rule, gap_or_risk, next_action, status, priority, llm_queryable, company_knowledge_candidate, memory_tags, source_skill_file, source_type)
VALUES ('D01-A09', DATE '2026-08-03', 'sarujanan', 'scwts', 'Supplier-to-Customer Workflow Tracking System', 'REQ-02', 'D01', 'validation', 'Validate all 18 dashboard fields independently against their sources', 'Wrote a standalone validator that re-derives every field from its original source and diffs it against the published payload, rather than trusting the builder''s own output. Covered Component SKU, Component Image, Component Created Date, Combo SKU, Combo Image, Combo Created Date, Listing Status, Marketplace, Listed Date, Impressions, Clicks, Orders, Units Sold, Revenue, Total Returns, Return Rate, Top Reason and Average Feedback. Result: 0 mismatches across 781 rows and 794 component cells.', 'PostgreSQL order_management_copy; Google Sheet; LEDs One cache', 'dashboard-v3-sql/validate_v3.py; dashboard-v3-sql/validation_v3.json', '18 fields checked; 0 mismatches; 781 rows; 209 components', TRUE, 'Independent re-derivation validator: never validate a pipeline using the pipeline''s own output', 'Every displayed field must equal an independent re-derivation from its source', 'Top Reason and Average Feedback remain unavailable - no reason data and no review table on this database', 'Decide whether V3 may read returns and feedback from LEDs One to close these two fields', 'completed', 'high', TRUE, TRUE, 'validation,independent-rederivation,zero-mismatch', '2026-07-31__sarujanan__scwts__REQ-02-D01.md', 'skill_file')
ON CONFLICT (project_code, activity_id) DO UPDATE SET activity_date=EXCLUDED.activity_date, developer=EXCLUDED.developer, project_name=EXCLUDED.project_name, requirement_id=EXCLUDED.requirement_id, deliverable_id=EXCLUDED.deliverable_id, activity_type=EXCLUDED.activity_type, activity_title=EXCLUDED.activity_title, activity_summary=EXCLUDED.activity_summary, systems_touched=EXCLUDED.systems_touched, files_touched=EXCLUDED.files_touched, evidence_refs=EXCLUDED.evidence_refs, reusable_asset_created=EXCLUDED.reusable_asset_created, reusable_pattern=EXCLUDED.reusable_pattern, validation_rule=EXCLUDED.validation_rule, gap_or_risk=EXCLUDED.gap_or_risk, next_action=EXCLUDED.next_action, status=EXCLUDED.status, priority=EXCLUDED.priority, llm_queryable=EXCLUDED.llm_queryable, company_knowledge_candidate=EXCLUDED.company_knowledge_candidate, memory_tags=EXCLUDED.memory_tags, source_skill_file=EXCLUDED.source_skill_file, source_type=EXCLUDED.source_type, updated_at=now();

INSERT INTO daily_task.tbl_scwts_sarujanan (activity_id, activity_date, developer, project_code, project_name, requirement_id, deliverable_id, activity_type, activity_title, activity_summary, systems_touched, files_touched, evidence_refs, reusable_asset_created, reusable_pattern, validation_rule, gap_or_risk, next_action, status, priority, llm_queryable, company_knowledge_candidate, memory_tags, source_skill_file, source_type)
VALUES ('D01-A10', DATE '2026-08-03', 'sarujanan', 'scwts', 'Supplier-to-Customer Workflow Tracking System', 'REQ-02', 'D01', 'deployment', 'Publish V3 to the Varman AIOS hub and rename the page slug', 'Published Dashboard V3 to the hub, then renamed the slug from supplier-to-customer-workflow-tracking-v3 to container-to-customer-workflow-tracking. Because the upsert key is member_name plus page_slug the hub has no rename operation, so the new slug was published and MD5-verified first and only then was the old row deleted, meaning the page was never unavailable. Republished after the image fix; the hub copy was verified byte-for-byte and confirmed to carry the corrected image URL.', 'varman_aios.hub_pages; local filesystem', 'dashboard-v2-update/push_to_hub.js; dashboard-v3/index.html', 'hub id 125 container-to-customer-workflow-tracking; MD5 99743871573da1746be779e17a76c7da matches local', FALSE, 'Rename a hub page by publish-verify-then-delete so the page is never offline', 'Hub html_content MD5 must equal the local file MD5 after every publish', 'None', 'None', 'completed', 'high', TRUE, TRUE, 'deployment,aios-hub,slug-rename,md5-verify', '2026-07-31__sarujanan__scwts__REQ-02-D01.md', 'skill_file')
